// Package openapispec builds the OpenAPI document served at /api/openapi.json.
//
// Two inputs, one output:
//
//   - api/grid/v1/grid.swagger.json — what protoc-gen-openapiv2 generates from
//     grid.proto (Swagger 2.0). It describes the GridService RPCs and nothing
//     else, and it is regenerated by `make proto`.
//   - api/grid/v1/openapi.overlay.yaml — what the generator cannot express: the
//     hand-built routes (the .geojson map layers, /api/v1/mesh/links, the ingest
//     write endpoint, /mcp, the spec itself), the error envelope's codeName, the
//     shared error responses, and the security scheme.
//
// Build converts the generated document to OpenAPI 3.0 (3.0 says nullable, oneOf
// and per-response content types, which Swagger 2.0 cannot), marks the
// properties the gateway can serialize as null (nullable.go, from the proto
// descriptor), completes the generated error responses (responses.go), merges the overlay into it under the rules in merge.go, checks
// every $ref resolves, validates the result with kin-openapi, and renders it
// with a stable key order. The output is api/grid/v1/openapi.json, which is
// committed and embedded.
package openapispec

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/getkin/kin-openapi/openapi2"
	"github.com/getkin/kin-openapi/openapi2conv"
	"github.com/getkin/kin-openapi/openapi3"
	"google.golang.org/protobuf/reflect/protoreflect"
	"gopkg.in/yaml.v3"
)

// Overlay is the hand-written half of the spec. The two sections differ only in
// who wins a collision with the generated document, which is the whole point of
// keeping them apart:
//
//   - Spec is content the overlay OWNS (routes the generator never sees, their
//     schemas, shared responses). Colliding with generated content is a build
//     error, so a route that moves into grid.proto cannot end up described twice.
//   - Defaults ANNOTATE generated content (an error example on a generated RPC, a
//     description on google.rpc.Status). The generated value wins wherever it
//     exists, so richer proto annotations take over without an overlay edit.
type Overlay struct {
	Spec     map[string]any `yaml:"spec"`
	Defaults map[string]any `yaml:"defaults"`
}

// Report lists what the merge did that a maintainer may want to act on. Every
// entry is a JSON pointer.
type Report struct {
	// Shadowed are Defaults entries the generated spec now supplies itself. They
	// no longer reach the output and can be deleted from the overlay.
	Shadowed []string
}

// Build produces the served OpenAPI document from the generated Swagger 2.0
// JSON and the overlay YAML. proto is the descriptor of the .proto file the
// swagger was generated from (gridv1.File_grid_proto); it decides which
// properties are nullable. A nil descriptor marks none.
func Build(swaggerJSON, overlayYAML []byte, proto protoreflect.FileDescriptor) ([]byte, Report, error) {
	base, err := convertToV3(swaggerJSON)
	if err != nil {
		return nil, Report{}, err
	}
	if err := markNullable(base, nullableFields(proto)); err != nil {
		return nil, Report{}, err
	}
	completeGeneratedResponses(base)
	ov, err := parseOverlay(overlayYAML)
	if err != nil {
		return nil, Report{}, err
	}
	var rep Report
	if err := mergeOwned(base, ov.Spec, ""); err != nil {
		return nil, rep, fmt.Errorf("overlay spec: %w", err)
	}
	if err := mergeDefaults(base, ov.Defaults, "", &rep); err != nil {
		return nil, rep, fmt.Errorf("overlay defaults: %w", err)
	}
	pruneUnusedTags(base)
	trimServerSlashes(base)
	if err := checkResponses(base); err != nil {
		return nil, rep, err
	}
	if err := checkRefs(base); err != nil {
		return nil, rep, err
	}
	out, err := encode(base)
	if err != nil {
		return nil, rep, err
	}
	if err := validate(out); err != nil {
		return nil, rep, err
	}
	return out, rep, nil
}

// convertToV3 converts the generated Swagger 2.0 document to OpenAPI 3.0 and
// returns it as a generic JSON tree, the form the merge works on.
func convertToV3(swaggerJSON []byte) (map[string]any, error) {
	var raw map[string]any
	if err := json.Unmarshal(swaggerJSON, &raw); err != nil {
		return nil, fmt.Errorf("parse generated swagger: %w", err)
	}
	keepRefSiblings(raw)
	pre, err := json.Marshal(raw)
	if err != nil {
		return nil, fmt.Errorf("re-encode generated swagger: %w", err)
	}
	var v2 openapi2.T
	if err := json.Unmarshal(pre, &v2); err != nil {
		return nil, fmt.Errorf("parse generated swagger: %w", err)
	}
	v3, err := openapi2conv.ToV3(&v2)
	if err != nil {
		return nil, fmt.Errorf("convert swagger 2.0 to openapi 3: %w", err)
	}
	b, err := json.Marshal(v3)
	if err != nil {
		return nil, fmt.Errorf("marshal converted spec: %w", err)
	}
	var tree map[string]any
	if err := json.Unmarshal(b, &tree); err != nil {
		return nil, fmt.Errorf("re-read converted spec: %w", err)
	}
	return tree, nil
}

// parseOverlay reads the overlay YAML and normalizes it to the same generic JSON
// tree the converted spec is in (string keys, float64 numbers), so equal values
// compare equal regardless of which side they came from.
func parseOverlay(overlayYAML []byte) (Overlay, error) {
	var raw map[string]any
	if err := yaml.Unmarshal(overlayYAML, &raw); err != nil {
		return Overlay{}, fmt.Errorf("parse overlay: %w", err)
	}
	for k := range raw {
		if k != "spec" && k != "defaults" {
			return Overlay{}, fmt.Errorf("overlay: unknown top-level key %q (want spec, defaults)", k)
		}
	}
	norm, err := normalize(raw)
	if err != nil {
		return Overlay{}, fmt.Errorf("overlay: %w", err)
	}
	b, err := json.Marshal(norm)
	if err != nil {
		return Overlay{}, fmt.Errorf("overlay: %w", err)
	}
	var ov Overlay
	if err := json.Unmarshal(b, &ov); err != nil {
		return Overlay{}, fmt.Errorf("overlay: %w", err)
	}
	return ov, nil
}

// normalize converts YAML's map[any]any (which yaml.v3 produces for a mapping
// with a non-string key, e.g. an unquoted `200:` response code) into
// map[string]any so the tree marshals as JSON.
func normalize(v any) (any, error) {
	switch t := v.(type) {
	case map[string]any:
		out := make(map[string]any, len(t))
		for k, val := range t {
			n, err := normalize(val)
			if err != nil {
				return nil, err
			}
			out[k] = n
		}
		return out, nil
	case map[any]any:
		out := make(map[string]any, len(t))
		for k, val := range t {
			n, err := normalize(val)
			if err != nil {
				return nil, err
			}
			out[fmt.Sprint(k)] = n
		}
		return out, nil
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			n, err := normalize(val)
			if err != nil {
				return nil, err
			}
			out[i] = n
		}
		return out, nil
	default:
		return v, nil
	}
}

// validate loads the rendered document with kin-openapi (which resolves every
// reference) and validates it against the OpenAPI 3.0 rules, including that each
// example conforms to its schema.
func validate(doc []byte) error {
	loader := openapi3.NewLoader()
	spec, err := loader.LoadFromData(doc)
	if err != nil {
		return fmt.Errorf("load merged spec: %w", err)
	}
	if err := spec.Validate(context.Background(), openapi3.EnableExamplesValidation()); err != nil {
		return fmt.Errorf("merged spec is invalid: %w", err)
	}
	return nil
}

// pruneUnusedTags drops top-level tags no operation carries. protoc-gen-openapiv2
// always lists the service name (GridService) as a tag even when every RPC is
// tagged by resource, and an empty group only clutters a generated UI.
func pruneUnusedTags(doc map[string]any) {
	used := map[string]bool{}
	paths, _ := doc["paths"].(map[string]any)
	for _, item := range paths {
		ops, _ := item.(map[string]any)
		for _, op := range ops {
			o, _ := op.(map[string]any)
			tags, _ := o["tags"].([]any)
			for _, t := range tags {
				if name, ok := t.(string); ok {
					used[name] = true
				}
			}
		}
	}
	tags, ok := doc["tags"].([]any)
	if !ok {
		return
	}
	kept := tags[:0]
	for _, t := range tags {
		if m, ok := t.(map[string]any); ok {
			if name, _ := m["name"].(string); !used[name] {
				continue
			}
		}
		kept = append(kept, t)
	}
	doc["tags"] = kept
}

// trimServerSlashes drops the trailing slash kin-openapi's v2→v3 conversion
// leaves on a server URL built from host + basePath "/": paths already start
// with "/", so "https://host/" + "/api/v1/..." would join to a double slash.
func trimServerSlashes(doc map[string]any) {
	servers, _ := doc["servers"].([]any)
	for _, s := range servers {
		if m, ok := s.(map[string]any); ok {
			if u, ok := m["url"].(string); ok {
				m["url"] = strings.TrimRight(u, "/")
			}
		}
	}
}
